corrected_code:
const express = require('express');
const OpenApiValidator = require('express-openapi-validator');
const path = require('path');
const { InvoiceDb } = require('../models/invoices');

const app = express();
app.use(express.json());

app.use(
  OpenApiValidator.middleware({
    apiSpec: path.join(__dirname, 'specs', 'billing-openapi.yaml'),
    validateRequests: true,
    validateResponses: false
  })
);

app.get('/api/v1/invoices/:invoiceId', async (req, res) => {
  if (!req.user || !req.user.organizationId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Enforce object-level authorization by scoping invoice search to the authenticated organization
  const invoice = await InvoiceDb.findOne({
    where: {
      id: req.params.invoiceId,
      organizationId: req.user.organizationId
    }
  });

  if (!invoice) {
    return res.status(404).json({ error: 'Invoice not found or access denied' });
  }

  res.json({
    id: invoice.id,
    customerName: invoice.customerName,
    lineItems: invoice.lineItems,
    totalAmount: invoice.totalAmount,
    taxId: invoice.taxId
  });
});

app.listen(5001);
